#!/usr/bin/env python3
"""Generates CUTLIST.md and BUDGET.md (+ budget.csv, drawings) from model.py / budget.py."""
import os, sys, io, contextlib
sys.path.insert(0, os.path.dirname(__file__))
import model as m, budget as b
OUT = os.path.join(os.path.dirname(__file__), "..")
def fi(x):  # inches -> feet-inches string
    ft, inch = divmod(x, 12); return f"{int(ft)}'-{inch:g}\""

# ---------------------------------------------------------------- CUTLIST
cut = []
cut.append("# Cut list and framing layout\n")
cut.append(f"> Generated by `tools/model.py` at an **assumed wall height H = {m.H:.0f}\"**. Measure the lowest ceiling point first, then re-run or use the formulas below. Every dimension here is derived, so changing H changes the list.\n")
cut.append("## Formulas (use these with the measured H)\n")
cut.append("| Dimension | Formula | At H = 96\" |\n|---|---|---|")
cut.append(f"| Stud / king length | H - 1.5 (PT plate) - 3 (double top plate) | {m.stud_len:g}\" |")
cut.append(f"| Header underside above slab | H - 3 - 11.5 (2x6 + 1/2\" ply + 2x6) | {m.open_h:g}\" |")
cut.append(f"| Jack length (sits on PT plate) | H - 3 - 11.5 - 1.5 | {m.jack_len:g}\" |")
cut.append(f"| Leaf height with 1-1/2\" flat threshold bar | H - 3 - 11.5 - 1/8 (top gap) - 1.5 (bar) - 1/4 (over bar) = H - 16.375 | {m.leaf_h:g}\" |")
cut.append(f"| Leaf height with no bar | H - 14.875 | {m.leaf_h_nobar:g}\" |")
cut.append("\nThe original plan's \"approx 77-3/4\"\" leaf height cannot be derived from its own framing; use the formula.\n")
cut.append("## Horizontal layout (x measured from the left exterior wall)\n")
cut.append("| Zone | x range | Notes |\n|---|---|---|")
cut.append(f"| Left jamb pack (jack + king) | 0 - 3\" | 3\" thick so 3\" hinge screws go through jack into king |")
cut.append(f"| Clear opening | 3\" - 87\" (7'-0\") | two 41-3/4\" leaves + three 1/8\" gaps = {m.leaf_pair_w:.3f}\" |")
cut.append(f"| Right jamb pack (jack + king) | 87\" - 90\" | |")
cut.append(f"| Fixed wall | 90\" - 228\" | PT plate runs 87\" - 228\" = {m.plate_right_len:g}\" = 11'-9\" (this is the plan's \"fixed 11'-9\"\", which includes the right jamb pack) |")
cut.append(f"| Opener centerline | 114\" (9'-6\") | 27\" right of the opening; **verify, many openers are not centered** |")
cut.append("\nString check: 3\" + 84\" + 141\" = 228\" = 19'-0\". The plan's dimensions close.\n")
cut.append("Fixed-wall stud centers (16\" OC from the right end): 227.25 (end stud), 212, 196, 180, 164, 148, 132, 100, then a nailer stud at 90-91.5\" so the board edge has bearing. The stud at 116\" is **omitted** for the opener notch and replaced by two trimmers at about 105.5\" and 122.5\" (notch roughly 14\" wide). Sheet edges then fall on 180\" and 132\".\n")
cut.append("## Framing cut list (2x4 SYP unless noted)\n")
cut.append("| Member | Qty | Length | Notes |\n|---|---|---|---|")
rows = [
 ("Fixed-wall studs (end + 7 intermediate + nailer)",9,m.stud_len,"16\" OC; two screwed sections"),
 ("Opener-notch trimmers",2,m.stud_len,"flank the notch"),
 ("Opener-notch head / sill",4,14,"2 doubled; height field-located"),
 ("Kings",2,m.stud_len,"outer member of each jamb pack"),
 ("Jacks",2,m.jack_len,"inner member; hinge screws pass jack -> king"),
 ("Double top plate - layer A",3,"96 + 96 + 36","joints stagger against layer B"),
 ("Double top plate - layer B",3,"48 + 96 + 84","screw to joists/blocking"),
 ("PT plate 2x4x12 (right pack + fixed wall)",1,m.plate_right_len,"on sill gasket, Tapcon ~32\" OC + ends"),
 ("PT left-pack pad",1,3.0,"offcut"),
 ("PT threshold bar, laid flat (removable)",1,m.OPEN_W,"carries bottom-bolt sockets; screwed to Tapcons so it unscrews"),
 ("Header 2x6x8",2,87,"between kings; 1/2\" ply spacer between them"),
 ("Plywood header spacer, 5-1/2\" strip",1,87,"from the 15/32\" sheet"),
]
for n,q,l,no in rows:
    cut.append(f"| {n} | {q} | {l if isinstance(l,str) else fi(l) if l>12 else str(l)+chr(34)} | {no} |")
cut.append("\n### Each leaf (two leaves, mirror images) - all 2x4 on edge\n")
cut.append("| Member | Qty | Length | Notes |\n|---|---|---|---|")
lw=[("Stiles (hinge pair + meeting pair, **doubled**)",4,m.leaf_h,"two screwed/glued together = 3\" wide x 3.5\" deep"),
    ("Rails: top, mid (lock rail), bottom",3,m.LEAF_W-6,"between stiles; mid rail centre 38\" above leaf bottom"),
    ("Center stile, upper segment",1,m.MID_SEG1,"between top rail and mid rail"),
    ("Center stile, lower segment",1,m.leaf_h-1.5-m.MID_SEG1-1.5-1.5,"between mid rail and bottom rail"),
    ("Z-brace",1,round(__import__('math').hypot(m.LEAF_W-6,m.leaf_h-3),2),"mitered both ends; low at hinge side, high at meeting side"),
    ("Blocking (gate wheel, rim lock)",2,10,"offcuts")]
for n,q,l,no in lw: cut.append(f"| {n} | {q} | {l:.3f}\" | {no} |")
cut.append("\n## Lumber to buy\n")
cut.append(f"- **2x4x8:** {m.STUDS_PACKED} boards packed by first-fit-decreasing (kerf 1/8\") + {m.SOFFIT_ALLOWANCE} for soffit/chase framing + 3 for crowned or split boards = **{m.STUDS_BUY}**. The plan said ~30. The difference is the doubled stiles (+4), the notch and the soffit.")
cut.append("- **2x4x12 PT:** 2 (plate; threshold bar + pad). Same as plan.")
cut.append("- **2x6x8:** **2** for the header pair (plan said 4 because it used 2x6 meeting stiles; see AUDIT item 1).")
cut.append("- **Plywood 15/32\" 4x8:** 1 (header spacer, soffit hatch, hatch cleats).\n")
cut.append("<details><summary>Board-by-board packing (2x4x8)</summary>\n")
for i,bn in enumerate(m.bins,1):
    cut.append(f"{i}. " + ", ".join(f"{n} {l:.2f}\"" for n,l in bn['cuts']) + f" (offcut {max(bn['left'],0):.2f}\")")
cut.append("\n</details>\n")
cut.append("## Sheet goods (4x8, 1/2\")\n")
cut.append(f"Per face: **5 sheets** works, with almost no waste: 3 sheets vertical for the 138\" fixed run (sheet edges on 180\" and 132\"), plus 2 sheets for the two leaf skins. Each leaf skin ({m.LEAF_W}\" x {m.leaf_h:.3f}\") leaves a 48\" x {96-m.leaf_h:.2f}\" offcut; two offcuts butt to make the 14.5\" x 90\" strip over the opening, and the 6.25\" side offcut rips into two 3\" strips for the jamb packs. Garage face = mold-resistant board (5 sheets); room face = regular (5 sheets, +1 for soffit/hatch backing). Ceiling: 8 sheets.\n")
cut.append("## Leaf weight\n")
cut.append(f"Estimated finished weight **~{m.LEAF_LB:.0f} lb per leaf** ({m.LEAF_AREA:.1f} sf face; frame ~1.28 lb/ft per 2x4; garage board 2.0 psf, room board 1.4 psf; 12 lb hardware). Plan figure was 110-130 lb. Treat 135-160 lb as the design load.\n")
cut.append("## Hardware\n")
cut.append("| Item | Qty | Notes |\n|---|---|---|")
for r in [("4.5\" NRP (non-removable pin) ball-bearing hinges","8 (4 per leaf)","3\" screws through jack into king. Verify rated load per hinge on the spec sheet; heavy-weight 5\" if the rating is below ~75 lb each"),
          ("Spring gate wheel 4\"","2","one per leaf at the meeting corner"),
          ("6\" barrel bolts","4","top + bottom per leaf, **room face**; bottom bolts engage the threshold bar"),
          ("Jimmy-proof rim deadbolt","1","room face of leaf A at ~38\"; strike through-bolted into leaf B's doubled stile"),
          ("EPDM bulb seal","~28 ft","jambs + header ~21 ft, astragal edge ~7 ft"),
          ("Astragal","1","on leaf B's meeting edge"),
          ("Adjustable door sweep","2","bottom of each leaf, seals to the bar"),
          ("Tapcon 3/16 x 3-1/4\" + 3/16\" masonry bit + hammer drill","~12 anchors","plate ~32\" OC + ends, threshold bar ends; bit and drill are not on the plan's list"),
          ("3\" structural screws, 1-5/8\" drywall screws (5 lb each)","-","plan carried $10-15; see BUDGET")]:
    cut.append(f"| {r[0]} | {r[1]} | {r[2]} |")
open(os.path.join(OUT,"CUTLIST.md"),"w").write("\n".join(cut).replace("$","\\$")+"\n")

# ---------------------------------------------------------------- BUDGET
buf=io.StringIO()
with contextlib.redirect_stdout(buf): r=b.main()
T=r["tot_plan"]; N=r["tot_now"]
bm=[]
bm.append("# Budget - re-added, corrected, and completed\n")
bm.append("> Unit prices are the original plan's \"checked 2026-11-19\" Home Depot prices. **They were not re-verified** (no store access); two flags below. Items marked *est.* are my estimates, not checked prices. Generated by `tools/budget.py`; line items are in `budget.csv`.\n")
bm.append("## 1. The plan's own arithmetic\n")
bm.append(f"Every line re-added: Phase 1 **${T[1]:,.2f}**, Phase 2 **${T[2]:,.2f}**, Phase 3 **${T[3]:,.2f}**, total **${r['plan_total']:,.2f}**. All match the plan's stated figures. The original plan's Phase 4 and full-project sums (which used 18K units) also check out (3,111 + 1,398 + 350 = 4,859; 3,111 + 2,309 + 1,000 = 6,420).\n")
bm.append("## 2. Corrections to quantities already on the list\n")
bm.append("| Phase | Item | Plan qty | Now | Unit | Delta | Why |\n|---|---|---|---|---|---|---|")
for row in r["rows"]:
    if row[2]!=row[3]: bm.append(f"| {row[0]} | {row[1]} | {row[2]} | {row[3]} | ${row[4]:,.2f} | {row[7]:+,.2f} | {row[8]} |")
bm.append(f"\nCorrected materials: Phase 1 **${N[1]:,.2f}**, Phase 2 **${N[2]:,.2f}**, Phase 3 **${N[3]:,.2f}**, total **${r['now_total']:,.2f}** (was $3,111.00).\n")
bm.append("## 3. Items missing from the plan's totals (estimates)\n")
bm.append("| ID | Item | Low | High | Note |\n|---|---|---|---|---|")
for a in r["A"]: bm.append(f"| {a[0]} | {a[1]} | ${a[2]:,} | ${a[3]:,} | {a[4]} |")
bm.append("\nA11 is labor, so no sales tax applies; A1-A10 are materials and are taxed at 7%.\n")
bm.append("## 4. Realistic totals\n")
bm.append("| | Low | High |\n|---|---|---|")
bm.append(f"| Corrected materials + added materials (A1-A10) | ${r['mat_lo']:,.0f} | ${r['mat_hi']:,.0f} |")
bm.append(f"| 7% sales tax | ${r['tax_lo']:,.0f} | ${r['tax_hi']:,.0f} |")
bm.append(f"| Electrician labor, Phase 3 (A11) | $200 | $600 |")
bm.append(f"| **Phases 1-3 total** | **${r['p13_lo']:,.0f}** | **${r['p13_hi']:,.0f}** |")
bm.append(f"| Phase 4 unit, Hessaire 12K 115V ($799 + tax) | ${799*1.07:,.0f} | ${799*1.07:,.0f} |")
bm.append(f"| Phase 4 services (115V circuit, pad/cover, permit) | ${r['svc'][0]:,} | ${r['svc'][1]:,} |")
lo=r['p13_lo']+799*1.07+r['svc'][0]; hi=r['p13_hi']+799*1.07+r['svc'][1]
bm.append(f"| **Full project, Hessaire 12K** | **${lo:,.0f}** | **${hi:,.0f}** |")
lo2=r['p13_lo']+2193.87*1.07+r['svc'][0]; hi2=r['p13_hi']+2193.87*1.07+r['svc'][1]
bm.append(f"| **Full project, MRCOOL 12K** | **${lo2:,.0f}** | **${hi2:,.0f}** |")
core_lo=r['p13_lo']-250*1.07; core_hi=r['p13_hi']-600*1.07
bm.append(f"\nIf you skip A10 (network gear you may already own), Phases 1-3 land at **${core_lo:,.0f} - ${core_hi:,.0f}**.\n")
bm.append("The plan's headline of \"$4,860-$5,510 with the Hessaire\" omitted sales tax, the electrician labor for Phase 3, the permit, the unpriced network gear and raceway, GFCI/breakers/wire, and realistic fasteners and paint. The plan is not wrong arithmetic - it is an incomplete list.\n")
bm.append("## 4a. Phase 4 changed from 18K to 12K\n")
bm.append("The plan now sizes Phase 4 at **12K** (see `SIZING.md`). Unit prices, from search results for Home Depot listings and **not verified at checkout**: Hessaire 12K 115V (H12HP1A) about $799 (a 208/230V model, H12HP2A, about $870); MRCOOL DIY 5th Gen 12K 115V about $2,194. The 18K units the plan priced were $1,398 and $2,309. Both 12K models are listed in 115V, so Phase 4 needs a **dedicated 115V 20A circuit** instead of a 240V one (confirm the nameplate MCA/MOCP before wiring); the electrician line is an estimate. A 230V variant exists for each if you prefer that.\n")
bm.append("## 5. Price flags\n")
bm.append("- **G-Floor Levant 7.5 x 17 slate grey:** the plan used $229.99/roll. One retailer search page showed the same roll at $379.99 and another at $229.00. If $379.99 is the Home Depot price, add **$300** to Phase 3. Re-check at checkout.\n- **Titebond sealant:** the case price ($106.48) is $79.86 more than the three tubes you need; buy tubes individually.\n- **Stall mats:** $359 at Home Depot; farm-supply mats typically about half.\n- **Mold Tough vs glass-mat board:** if you switch the garage face to glass-mat (DensArmor Plus class) to honor the plan's own spec, the price is not on the list; the plan's own note says about $25-$50 more for the wall.\n- **Surface-mount frames:** $171.96 for 4 (the plan flags a ~$107 alternative as unverified).\n")
bm.append("## 6. Phase estimates vs priced lists\n")
bm.append("| Phase | Plan's rough range | Priced materials (plan) | Priced materials (corrected) |\n|---|---|---|---|")
bm.append(f"| 1 Partition + hinged section | $450-$750 | ${T[1]:,.2f} | ${N[1]:,.2f} |")
bm.append(f"| 2 Ceiling, R-30, lighting, fans | $850-$1,150 | ${T[2]:,.2f} | ${N[2]:,.2f} |")
bm.append(f"| 3 Flooring, electrical, small stuff | $860-$1,310 | ${T[3]:,.2f} | ${N[3]:,.2f} |")
bm.append("\nPhases 1 and 2 priced out above the rough ranges *before* tax, labor or the additions in section 3.\n")
open(os.path.join(OUT,"BUDGET.md"),"w").write("\n".join(bm).replace("$","\\$")+"\n")
print(buf.getvalue()); print("wrote CUTLIST.md BUDGET.md")
